CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"ce708abd-4304-5a46-8927-d6e77e9fbfce","source_id":"0333","name_en":"dumbbell kickback","name_ar":"\u0631\u0634\u0648\u0629 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell kickback"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell kickback"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\nBend your knees slightly and hinge forward at the hips, keeping your back straight.\nBring your upper arms close to your sides, with your elbows bent at a 90-degree angle.\nExtend your arms straight back, squeezing your triceps at the top of the movement.\nPause for a moment, then slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u062c\u0639\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u0642\u0631\u064a\u0628\u062a\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643\u060c \u0645\u0639 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0333","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0333-W6PxUkg.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0333-W6PxUkg.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6116a803-8360-584c-882c-6e89792a10a3","source_id":"1734","name_en":"dumbbell kickbacks on exercise ball","name_ar":"\u0639\u0645\u0648\u0644\u0627\u062a \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell kickbacks on exercise ball"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell kickbacks on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and your back straight.\nHold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.\nExtend your arms straight back, squeezing your triceps at the top of the movement.\nPause for a moment, then slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062f\u0627\u062e\u0644 \u0648\u062b\u0646\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1734","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders","back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1734-cAvTaSg.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1734-cAvTaSg.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"24821f9f-fd94-59a5-84d2-5f136a2b8a78","source_id":"1660","name_en":"dumbbell kneeling bicep curl exercise ball","name_ar":"\u0643\u0631\u0629 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0648\u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646","match_names":["dumbbell kneeling bicep curl exercise ball"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell kneeling bicep curl exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Kneel on the floor with an exercise ball in front of you.\nPlace your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.\nKeeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.\nContinue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0643\u0639 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0623\u0645\u0627\u0645\u0643.\n\u0636\u0639 \u0645\u0631\u0641\u0642\u064a\u0643 \u0641\u0648\u0642 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1660","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1660-2JCuFTU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1660-2JCuFTU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"75099793-4b69-527a-8cdc-d2114d298725","source_id":"0334","name_en":"dumbbell lateral raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u062c\u0627\u0646\u0628\u064a","match_names":["dumbbell lateral raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell lateral raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.\nKeep your back straight and engage your core.\nRaise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0628\u0633\u064a\u0637 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0334","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0334-DsgkuIt.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0334-DsgkuIt.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"19ecda4b-5f3f-54f8-8c58-6f09be8a5983","source_id":"0335","name_en":"dumbbell lateral to front raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0646 \u0627\u0644\u062c\u0627\u0646\u0628 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645","match_names":["dumbbell lateral to front raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell lateral to front raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.\nKeep your back straight and engage your core.\nRaise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nNext, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0633\u0645\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0628\u0633\u064a\u0637 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0628\u0639\u062f \u0630\u0644\u0643\u060c \u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0623\u0645\u0627\u0645\u0643 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0335","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0335-xMjBKwn.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0335-xMjBKwn.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"756db5f6-13a4-5262-8304-ec124f91610c","source_id":"0336","name_en":"dumbbell lunge","name_ar":"\u0627\u0646\u062f\u0641\u0627\u0639 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell lunge"],"muscle":"glutes","equipment":"dumbbell","aliases":["dumbbell lunge"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\nTake a step forward with your right foot, lowering your body into a lunge position.\nKeep your back straight and your chest up as you lower your body.\nPush through your right heel to return to the starting position.\nRepeat with your left leg.\nAlternate legs for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0623\u062b\u0646\u0627\u0621 \u062e\u0641\u0636 \u062c\u0633\u0645\u0643.\n\u0627\u062f\u0641\u0639 \u0628\u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0623\u0631\u062c\u0644 \u0628\u062f\u064a\u0644\u0629 \u0644\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0336","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0336-RRWFUcw.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0336-RRWFUcw.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b31f675e-6d11-50c1-8b91-342114a7bb91","source_id":"1658","name_en":"dumbbell lunge with bicep curl","name_ar":"\u0627\u0646\u062f\u0641\u0627\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0639 \u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646","match_names":["dumbbell lunge with bicep curl"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell lunge with bicep curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.\nTake a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.\nAs you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.\nPause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.\nRepeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639. \u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0645\u062b\u0646\u064a\u0629 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629 \u0648\u064a\u062c\u0628 \u0623\u0646 \u062a\u062d\u0648\u0645 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0641\u0648\u0642 \u0627\u0644\u0623\u0631\u0636 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0646\u062f\u0641\u0627\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0642\u0645 \u0628\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0639\u0628\u0631 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0643\u0631\u0631 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639 \u0648\u062b\u0646\u064a \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631\u060c \u0645\u0639 \u0627\u0644\u062a\u0642\u062f\u0645 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1658","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["quadriceps","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1658-Mz6lLcW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1658-Mz6lLcW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b80b90d3-7c45-51a0-8692-015cfbd3b429","source_id":"0337","name_en":"dumbbell lying extension (across face)","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 (\u0639\u0628\u0631 \u0627\u0644\u0648\u062c\u0647)","match_names":["dumbbell lying extension (across face)"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell lying extension (across face)"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\nHold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.\nKeeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.\nPause for a moment, then contract your triceps to bring the dumbbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0631\u0623\u0633\u0643 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0642\u0648\u0633 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0633\u0627\u0639\u062f\u0627\u0643 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0644\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0337","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0337-L2V5Nan.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0337-L2V5Nan.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"75e8c7af-fbb6-54fb-8180-e74634d5b085","source_id":"1729","name_en":"dumbbell lying alternate extension","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0643\u0630\u0628 \u062a\u0645\u062f\u064a\u062f \u0628\u062f\u064a\u0644","match_names":["dumbbell lying alternate extension"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell lying alternate extension"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with a dumbbell in each hand, palms facing each other.\nExtend your arms straight up over your chest, keeping a slight bend in your elbows.\nLower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.\nPause for a moment at the bottom, then raise the dumbbell back up to the starting position.\nRepeat with the other arm, alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u0623\u062d\u062f \u0627\u0644\u062f\u0645\u0628\u0644\u064a\u0646 \u0646\u062d\u0648 \u0631\u0623\u0633\u0643\u060c \u0645\u0639 \u062b\u0646\u064a \u0627\u0644\u0645\u0631\u0641\u0642\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649 \u0645\u0645\u062a\u062f\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0645\u0639 \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1729","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1729-NfP83rA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1729-NfP83rA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"89592836-bf0a-503a-8435-8f9086feec63","source_id":"0338","name_en":"dumbbell lying elbow press","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0643\u0648\u0639 \u0628\u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell lying elbow press"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell lying elbow press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.\nLower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.\nPause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0628\u062d\u064a\u062b \u062a\u0648\u0627\u062c\u0647 \u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636\u060c \u0648\u062a\u0645\u062a\u062f \u0627\u0644\u0630\u0631\u0627\u0639\u0627\u0646 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0338","license":"M