u0639\u0644\u0648\u064a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0648\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u064a\u062f\u0643 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643\u060c \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0633\u0627\u0639\u062f\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0642\u062f\u0631 \u0627\u0644\u0625\u0645\u0643\u0627\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0639\u062f\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0863","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["rotator cuff","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0863-bmBf7LN.jpg","gif":"https://raw.githubuserco