0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0339","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0339-FkBIE6a.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0339-FkBIE6a.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"53c44fe1-75bb-5e05-8dff-b9a204d4e44b","source_id":"0340","name_en":"dumbbell lying hammer press","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0643\u0630\u0628 \u0627\u0644\u0645\u0637\u0631\u0642\u0629 \u0627\u0644\u0635\u062d\u0627\u0641\u0629","match_names":["dumbbell lying hammer press"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell lying hammer press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.\nLower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.\nPress the dumbbells back up to the starting position, fully extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0628\u062d\u064a\u062b \u062a\u0648\u0627\u062c\u0647 \u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636\u060c \u0648\u062a\u0645\u062a\u062f \u0627\u0644\u0630\u0631\u0627\u0639\u0627\u0646 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0340","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0340-7gdLIXa.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0340-7gdLIXa.gif","author":"G