liases":["dumbbell lying one arm supinated triceps extension"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with your back and head supported, and your feet flat on the ground.\nHold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.\nKeeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.\nPause for a moment at the bottom, then extend your arm back up to the starting position.\nRepeat for the desired number of repetitions, then switch arms.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u062f\u0639\u0645 \u0638\u0647\u0631\u0643 \u0648\u0631\u0623\u0633\u0643\u060c \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0643\u062a\u0641\u0643.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0346","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0346-zZlORz6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0346-zZlORz6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d05860d6-f687-5be1-89f3-0071b4293945","source_id":"0347","name_en":"dumbbell lying pronation","name_ar":"\u0646\u0637\u0642 \u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0643\u0630\u0628","match_names":["dumbbell lying pronation"],"muscle":"forearms","equipment":"dumbbell","aliases":["dumbbell lying pronation"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.\nRotate your palms so they are facing up.\nKeeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.\nInhale and slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0635\u062f\u0631\u0643 \u0645\u062a\u062c\u0647\u064b\u0627 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644 \u0623\u062b\u0646\u0627\u0621 \u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0648\u062c\u0647\u0647\u0645\u0627 \u0644\u0623\u0633\u0641\u0644.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0347","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0347-mym4hJo.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0347-mym4hJo.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5db84f9d-376a-5d23-8bcc-6e2378108e20","source_id":"2705","name_en":"dumbbell lying pronation on floor","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0644\u0642\u0627\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636","match_names":["dumbbell lying pronation on floor"],"muscle":"forearms","equipment":"dumbbell","aliases":["dumbbell lying pronation on floor"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.\nRotate your palms so they are facing down towards the floor.\nKeeping your arms straight, lift the dumbbells off the floor by contracting your forearms.\nContinue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.\nHold for a moment, then slowly lower the dumbbells back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0642\u0628\u0636 \u0633\u0627\u0639\u062f\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0633\u0627\u0639\u062f\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u0646\u062a\u0638\u0631 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2705","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2705-7RWNjiB.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2705-7RWNjiB.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c7633ebd-e86a-52c3-82ea-c945beec5dc9","source_id":"1284","name_en":"dumbbell lying pullover on exercise ball","name_ar":"\u0633\u062a\u0631\u0629 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0644\u0642\u0627\u0629 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell lying pullover on exercise ball"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell lying pullover on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball and roll forward until your upper back is resting on the ball.\nHold a dumbbell with both hands and extend your arms straight up over your chest.\nSlowly lower the dumbbell behind your head while keeping your arms straight.\nPause for a moment, then raise the dumbbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u062a\u0645\u0631\u064a\u0646 \u0648\u062a\u062f\u062d\u0631\u062c \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0633\u062a\u0642\u0631 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1284","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders","back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1284-iK59oEA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1284-iK59oEA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e78e6e62-13f1-5826-8dc0-6afed6417599","source_id":"1328","name_en":"dumbbell lying rear delt row","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0644\u0642\u0627\u0629 \u0641\u064a \u0635\u0641 \u0627\u0644\u062f\u0644\u062a\u0627 \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["dumbbell lying rear delt row"],"muscle":"back","equipment":"dumbbell","aliases":["dumbbell lying rear delt row"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.\nExtend your arms straight down towards the floor, keeping a slight bend in your elbows.\nEngaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0633\u0637\u062d \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0646\u062d\u0648 \u0627\u0644\u062f\u0627\u062e\u0644.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1328","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["shoulders","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1328-XUUD0Fs.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1328-XUUD0Fs.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6d23fefd-0239-59bf-82dc-34dd8069ae9c","source_id":"0348","name_en":"dumbbell lying rear lateral raise","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0633\u062a\u0644\u0642\u064a\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0631\u0641\u0639 \u0627\u0644\u062c\u0627\u0646\u0628\u064a \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["dumbbell lying rear lateral raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell lying rear lateral raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.\nExtend your arms straight down towards the floor, keeping a slight bend in your elbows.\nEngaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0633\u0637\u062d \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0645\u0639 \u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0643\u062a\u0641\u064a\u0643\u060c \u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0348","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","rhomboids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0348-53Ttlck.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0348-53Ttlck.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0a12892a-24cc-5c7d-8e9f-3ab4711a6b32","source_id":"1735","name_en":"dumbbell lying single extension","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0643\u0630\u0628 \u062a\u0645\u062f\u064a\u062f \u0648\u0627\u062d\u062f","match_names":["dumbbell lying single extension"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell lying single extension"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.\nLower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.\nPause briefly at the bottom of the movement, then extend your arm back to the starting position.\nRepeat for the desired number of repetitions, then switch arms.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0648\u0630\u0631\u0627\u0639\u0643 \u0645\u0645\u062a\u062f\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u062a\u062d\u0643\u0645 \u0628\u0647\u0627 \u0646\u062d\u0648 \u062c\u0628\u0647\u062a\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0641\u062a\u0631\u0629 \u0648\u062c\u064a\u0632\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1735","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1735-6MfS53i.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1735-6MfS53i.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"37642dc2-283e-515a-8d78-f3b816811ebf","source_id":"0349","name_en":"dumbbell lying supination","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0627\u0644\u0643\u0630\u0628 \u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621","match_names":["dumbbell lying supination"],"muscle":"forearms","equipment":"dumbbell","aliases":["dumbbell lying supination"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with your feet flat on the ground.\nHold a dumbbell in each hand with your palms facing up and your arms fully extended.\nKeeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.\nPause for a moment at the top, then slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0642\u0628\u0636 \u0633\u0627\u0639\u062f\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0349","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0349-M2Pm3zj.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0349-M2Pm3zj.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e18353bd-d2b0-53b4-86e1-8ad6aa4418ef","source_id":"2706","name_en":"dumbbell lying supination on floor","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0633\u062a\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636","match_names":["dumbbell lying supination on floor"],"muscle":"forearms","equipment":"dumbbell","aliases":["dumbbell lying supination on floor"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.\nRotate your palms to face up, keeping your elbows close to your sides.\nSlowly curl the dumbbells towards your shoulders, squeezing your forearms.\nPause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0633\u0627\u0639\u062f\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2706","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2706-rEhi2o5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2706-rEhi2o5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"81b90d98-f7ed-5415-859c-30183462a9be","source_id":"1661","name_en":"dumbbell lying supine biceps curl","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0633\u062a\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u062d\u0644\u064a\u0642\u0629","match_names":["dumbbell lying supine biceps curl"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell lying supine biceps curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with your back and head supported, and your feet flat on the ground.\nHold a dumbbell in each hand with your palms facing up and your arms fully extended.\nKeeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u062f\u0639\u0645 \u0638\u0647\u0631\u0643 \u0648\u0631\u0623\u0633\u0643\u060c \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1661","license":"MIT"},"translation":{"provider