0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0627\u0644\u0645\u0634\u064a \u0628\u0642\u062f\u0645\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u062f\u062d\u0631\u062c\u0629 \u0627\u0644\u0643\u0631\u0629 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062f\u0639\u0645 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629 \u0648\u064a\u0643\u0648\u0646 \u0631\u0623\u0633\u0643 \u0648\u0631\u0642\u0628\u062a\u0643 \u0648\u0643\u062a\u0641\u064a\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0643\u0631\u0629.\n\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0645\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0625\u0644\u0649 \u0627\u0644\u062f\u0627\u062e\u0644.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0630\u0631\u0627\u0639\u0643 \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643 \u0644\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1286","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1286-Bpkf41o.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1286-Bpkf41o.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4658c5d8-85ce-576e-8cd7-41973a92e3af","source_id":"0353","name_en":"dumbbell one arm concentration curl (on stability ball)","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 (\u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a)","match_names":["dumbbell one arm concentration curl (on stability ball)"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell one arm concentration curl (on stability ball)"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\nHold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.\nRest your elbow on the inside of your thigh, just above the knee.\nKeeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.\nPause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.\nRepeat for the desired number of repetitions, then switch arms and repeat.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0623\u0639\u0644\u0649 \u0648\u0630\u0631\u0627\u0639\u0643 \u0645\u0645\u062a\u062f\u0629 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u0645\u0631\u0641\u0642\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0645\u0646 \u0641\u062e\u0630\u0643\u060c \u0641\u0648\u0642 \u0627\u0644\u0631\u0643\u0628\u0629 \u0645\u0628\u0627\u0634\u0631\u0629.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0