28\u0642\u0628\u0636\u0629 \u0645\u062d\u0627\u064a\u062f\u0629 (\u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0633\u0645\u0643).\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627\u060c \u062b\u0645 \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0646\u0634\u0642 \u0648\u0623\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1663","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1663-4dF3maG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1663-4dF3maG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9020316a-3794-5a93-8277-ec703af1c7cf","source_id":"1621","name_en":"dumbbell one arm hammer press on exercise ball","name_ar":"\u0627\u0636\u063a\u0637 \u0628\u0645\u0637\u0631\u0642\u0629 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell one arm hammer press on exercise ball"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell one arm hammer press on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and your back straight.\nHold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.\nPlace your other hand on your hip for stability.\nPress the dumbbell upwards, extending your arm fully.\nPause for a moment at the top, then slowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch arms.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u062f\u0627\u062e\u0644 \u0648\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u0623\u062e\u0631\u0649 \u0639\u0644\u0649 \u0648\u0631\u0643\u0643 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1621","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders","chest"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1621-VYmYxK5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1621-VYmYxK5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"00151fb0-f276-5eb8-8406-92b3140a909f","source_id":"1289","name_en":"dumbbell one arm incline chest press","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0635\u062f\u0631 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629","match_names":["dumbbell one arm incline chest press"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell one arm incline chest press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Adjust the incline bench to a 45-degree angle.\nSit on the bench with your back against the pad and feet flat on the ground.\nHold a dumbbell in one hand with an overhand grip, resting it on your shoulder.\nPush the dumbbell up and away from your body, extending your arm fully.\nPause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\nRepeat for the desired number of repetitions, then switch to the other arm.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0639\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u062b\u0645 \u0636\u0639\u0647 \u0639\u0644\u0649 \u0643\u062a\u0641\u0643.\n\u0627\u062f\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1289","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1289-PDaMuyV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1289-PDaMuyV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e780dcda-a115-57f5-8786-88838c5a2ac2","source_id":"0354","name_en":"dumbbell one arm kickback","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0631\u0634\u0648\u0629 \u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629","match_names":["dumbbell one arm kickback"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell one arm kickback"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.\nBend your knees slightly and hinge forward at the hips, keeping your back straight.\nBring your right elbow up to your side, keeping it bent at a 90-degree angle.\nExtend your right arm straight back, squeezing your triceps at the top of the movement.\nSlowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u0631\u0641\u0639 \u0645\u0631\u0641\u0642\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647 \u0645\u062b\u0646\u064a\u064b\u0627 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0354","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0354-bQy2Eni.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0354-bQy2Eni.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"40d4a525-725f-58fa-84ee-50a5f1611fa8","source_id":"0355","name_en":"dumbbell one arm lateral raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0628\u0634\u0643\u0644 \u062c\u0627\u0646\u0628\u064a","match_names":["dumbbell one arm lateral raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell one arm lateral raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.\nKeep your back straight and your core engaged throughout the exercise.\nRaise the dumbbell to the side, keeping your arm straight and your palm facing down.\nContinue lifting until your arm is parallel to the ground.\nPause for a moment at the top, then slowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch to the other arm.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0633\u0645\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0648\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0630\u0631\u0627\u0639\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0355","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0355-n5cWCsI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0355-n5cWCsI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b6286605-432a-5572-889d-e8ac00ffc711","source_id":"0356","name_en":"dumbbell one arm lateral raise with support","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u0627\u0644\u062f\u0639\u0645","match_names":["dumbbell one arm lateral raise with support"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell one arm lateral raise with support"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.\nPlace your other hand on a stable surface, such as a bench or wall, for support.\nKeep your back straight and engage your core.\nRaise the dumbbell out to the side, keeping your arm straight and your palm facing down.\nContinue lifting until your arm is parallel to the ground.\nPause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u064a\u062f \u0648\u0627\u062d\u062f\u0629\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0633\u0645\u0643.\n\u0636\u0639 \u064a\u062f\u0643 \u0627\u0644\u0623\u062e\u0631\u0649 \u0639\u0644\u0649 \u0633\u0637\u062d \u062b\u0627\u0628\u062a\u060c \u0645\u062b\u0644 \u0645\u0642\u0639\u062f \u0623\u0648 \u062c\u062f\u0627\u0631\u060c \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0648\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0630\u0631\u0627\u0639\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628